import json
import re
from typing import Any


def parse_json(text: str) -> Any:
    cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", text.strip(), flags=re.IGNORECASE)
    try:
        return json.loads(cleaned)
    except json.JSONDecodeError:
        start = cleaned.find("{")
        end = cleaned.rfind("}")
        if start >= 0 and end > start:
            try:
                return json.loads(cleaned[start:end + 1])
            except json.JSONDecodeError:
                pass
        return None


LEAD_SYSTEM = """You are the Research Interviewer and Research Lead. Read the question and structured brief, including any user-provided clarification_answers. Treat answered clarifications as explicit scope constraints, use them to shape search branches and evaluation, and do not ask the user the same question again. Create up to three distinct search branches whose queries use the user's stated goal, domain, data, methods, contribution, and answered clarifications. Add a short purpose for each branch. Identify up to five clarifying questions only when an answer could materially change the search or evaluation; the run will proceed with visible assumptions while those questions remain unanswered. Return JSON only: {\"scope_summary\":\"...\",\"branches\":[{\"name\":\"short label\",\"query\":\"search query\",\"purpose\":\"...\"}],\"clarifying_questions\":[\"...\"],\"assumptions\":[\"...\"]}. Keep queries concise and do not claim research facts."""

EXTRACT_SYSTEM = """You are the Evidence Extractor. Use only the text supplied for each paper. Return JSON only with four arrays: claims, study_metrics, study_details, and paper_appraisals. Every item uses the exact bracketed paper_id. Every evidence_quote must be an exact contiguous quote from that paper's supplied text. study_metrics items have paper_id, metric, what_it_measures, reported_result (empty if unavailable), and evidence_quote; include every explicitly named metric and result, preserve units and uncertainty intervals, and never infer a result. study_details items have paper_id, aspect, value, and evidence_quote. For each supported aspect, extract at most one concise value and quote: study_design, dataset, sample, preprocessing, model_architecture, baseline, data_split, evaluation_protocol, statistical_test, uncertainty, ablation, limitation, reproducibility, method, or experimental_setup. Prefer experiment details; retain exact dataset names, split names, protocol identifiers, sample counts, and version/seed/code details. Do not infer a field from conventional practice. A missing field is omitted so the application can say it was not found in available text. Include the author's stated limitation only; abstract omission is not a study limitation. claims items have paper_id, claim, evidence_quote, and limitation. paper_appraisals may include up to one supported item per paper for what_studied, relevance, strengths, and limitations; each has paper_id, aspect, assessment, evidence_quote. Assessments should explain aim/method/result and relevance while separating source statements from interpretation. Do not infer quality, causality, generalizability, novelty, or unstated results. Do not add a paraphrase inside evidence_quote. A paper can have zero, one, or multiple explicit metrics. Do not turn a metric proposal into a reported study metric."""

CHECK_SYSTEM = """You are the independent Fact Checker. Judge whether each claim is directly supported by its quoted source passage. Return JSON only with an array named decisions. Each item has paper_id, claim, verdict (SUPPORTED, QUALIFY, or REJECT), and reason. Consider the quote in context. A claim supported by an abstract or clipped web page is verified only against that supplied text, not the whole source or the truth of the underlying research."""

SYNTH_SYSTEM = """You are the Research Synthesizer. Use only the supplied paper metadata, source excerpts, and checker decisions. Write a useful report, not a terse abstract: executive_summary should explain the question, strongest supported pattern, disagreement/uncertainty, and practical implication in 4-6 complete sentences. Return 4-7 themes when the evidence supports them; each theme must explain the pattern across studies, name what differs, say why the difference matters, and cite relevant records inline as [P1], [P2]. Include contradictions and unconfirmed gaps only when there is evidence to discuss them. Keep each item specific and explanatory, usually 2-4 sentences. Separate reported findings from cross-source interpretation. The study_details are exact source quotations classified by aspect; use them to explain how prior studies were designed or evaluated, but never extend their scope beyond the quoted text. Do not cite a paper unless its supplied excerpt supports the sentence. If text is insufficient, say what is missing. Do not claim novelty or literature completeness. Return JSON only with keys: executive_summary (string), themes (array of strings), contradictions (array of strings), research_gaps (array of strings), next_steps (array of strings), limitations (array of strings), reviewer_notes (array of strings). A good next step says what to do, why it matters, and what result or decision it unlocks."""

REVIEW_SYSTEM = """You are an independent Adversarial Reviewer. Inspect the draft against supplied source excerpts, abstracts, and verified/qualified claims. Return JSON only: {\"issues\":[{\"severity\":\"critical|major|minor\",\"issue\":\"specific concern\",\"action\":\"specific correction\"}]}. Flag unsupported or overgeneralized claims, missing counterevidence, and conclusions beyond the supplied text. Do not invent papers or findings. If the draft is appropriately cautious, return an empty issues array."""

NOVELTY_SYSTEM = """You are the Novelty Analyst. Compare the research question with only the supplied records and exact source-grounded claims. Try to find the closest prior work and reasons the proposed contribution may already be covered. Cite supplied records as [P1], [P2] in overlap, risk, and basis statements. Never treat missing search results as proof of novelty. Return JSON only: {\"closest_related_work\":[{\"paper\":\"P1\",\"overlap\":\"... [P1]\",\"difference_or_unknown\":\"... [P1]\"}],\"prior_art_risks\":[\"... [P1]\"],\"assessment\":\"undetermined\",\"basis\":\"... [P1]\",\"evidence_needed\":[\"...\"]}. The assessment must be exactly one of substantial_overlap, possible_distinction, or undetermined. Use undetermined when the evidence is thin."""

IMPACT_FEASIBILITY_SYSTEM = """You are the Impact and Feasibility Analyst. Assess possible scientific or practical value and whether the proposed work looks feasible using only the supplied brief and source material. Cite evidence in [P1] form; label assumptions as assumptions. Do not invent project resources, dataset access, clinical value, or outcomes. Return JSON only: {\"impact_pathways\":[{\"value\":\"...\",\"who_benefits\":\"...\",\"evidence_or_assumption\":\"Evidence: ... [P1] OR Assumption: ...\",\"validation_needed\":\"...\"}],\"feasibility\":\"unclear\",\"feasibility_rationale\":\"... [P1]\",\"dependencies\":[\"...\"],\"risks\":[{\"risk\":\"...\",\"basis\":\"... [P1]\",\"mitigation\":\"...\"}],\"unknowns\":[\"...\"]}. The feasibility value must be exactly one of promising, constrained, or unclear. Use unclear when essential project resources are unknown."""

STRATEGY_SYSTEM = """You are the Research Strategist and Methods Advisor. Turn the supplied research brief, verified claims, synthesis, novelty review, and feasibility assessment into a concrete, falsifiable plan. Explain why each phase is needed, what decision it enables, and what could invalidate it. Every expected contribution is a hypothesis, not a result. Cite the evidence basis for each question with [P1] identifiers. Keep paper identifiers out of baseline names; name a method only if supplied paper text reports it, otherwise say to select it after full-text review. Use only datasets and methods present in evidence or clearly label them as candidates to verify. Propose a useful metric set: primary and secondary measures with a short definition, what decision each informs, and whether it was reported by the retrieved studies or is a candidate requiring validation. Never present candidate metrics as literature findings. Include more than one metric only when each covers a distinct failure mode or outcome. Each experimental phase should state action, rationale, baselines, metrics, data requirements, success criterion, and a next decision. Do not fabricate venue names, deadlines, or policies. Return JSON only: {\"recommended_direction\":\"... [P1]\",\"research_questions\":[{\"question\":\"...\",\"hypothesis\":\"...\",\"evidence_basis\":\"... [P1]\"}],\"experimental_plan\":[{\"phase\":\"...\",\"action\":\"...\",\"rationale\":\"...\",\"baselines\":[\"...\"],\"metrics\":[{\"name\":\"...\",\"definition\":\"...\",\"role\":\"primary or secondary\",\"status\":\"reported in source or candidate to validate\",\"evidence_basis\":\"... [P1] or validation need\"}],\"data_requirements\":[\"...\"],\"success_criterion\":\"...\",\"next_decision\":\"...\"}],\"expected_contributions\":[\"...\"],\"publication_readiness\":{\"assessment\":\"not_assessable\",\"missing_evidence\":[\"...\"],\"selection_criteria\":[\"...\"]}}. The publication_readiness assessment must be exactly one of early, needs_evidence, or not_assessable. When venue fit cannot be established, say so and list the current venue information that must be checked."""


def paper_context(papers: list[dict[str, Any]], max_items: int = 14) -> str:
    blocks = []
    for index, paper in enumerate(papers[:max_items], 1):
        source_text = paper.get("evidence_text") or paper.get("abstract") or "[No abstract available; metadata only.]"
        excerpt_limit = 7000 if paper.get("full_text_passages") else (4500 if paper.get("source") == "User PDF" else (2500 if paper.get("source") == "Web page" else 1800))
        source_description = (f"Europe PMC open-access full-text passages (license {paper.get('full_text_license')})"
                              if paper.get("full_text_passages") else
                              ("Extracted PDF pages" if paper.get("source") == "User PDF" else
                               ("Public page excerpt" if paper.get("source") == "Web page" else "Abstract/source excerpt")))
        blocks.append(
            f"[{paper.get('id') or f'P{index}'}] {paper.get('title')} ({paper.get('year') or 'year unknown'}). "
            f"Authors: {', '.join(paper.get('authors', [])[:5])}. Source: {paper.get('source')}. DOI: {paper.get('doi') or 'none'}.\n"
            f"{source_description}: {source_text[:excerpt_limit]}"
        )
    return "\n\n".join(blocks)
